using Aspire.Hosting.Testing;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Xunit;

namespace MyApp.AppHost.Evaluation;

/// <summary>
/// Provides shared infrastructure for spinning up the AppHost under evaluation.
/// </summary>
public sealed class EvaluationHarness : IAsyncLifetime
{
    private DistributedApplication? _app;

    public DistributedApplication App => _app ?? throw new InvalidOperationException("Harness not initialized.");

    public async ValueTask InitializeAsync()
    {
        var builder = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        _app = await builder.BuildAsync();
        await _app.StartAsync();
    }

    public async ValueTask DisposeAsync()
    {
        if (_app is not null)
        {
            await _app.StopAsync();
            await _app.DisposeAsync();
        }
    }
}

using Aspire.Hosting;
using Aspire.Hosting.Testing;
using Microsoft.Extensions.DependencyInjection;
using Xunit;

namespace MyApp.AppHost.Evaluation;

/// <summary>
/// Evaluation: validates the agentic app starts and all resources become healthy.
/// </summary>
public sealed class AppStartsTests : IAsyncLifetime
{
    private readonly EvaluationHarness _harness = new();

    public ValueTask InitializeAsync() => _harness.InitializeAsync();
    public ValueTask DisposeAsync() => _harness.DisposeAsync();

    [Fact]
    public void AppHost_Starts_Successfully()
    {
        Assert.NotNull(_harness.App);
    }

    [Fact]
    public async Task All_Resources_Reach_Running_State()
    {
        var resourceNotificationService = _harness.App.Services.GetRequiredService<ResourceNotificationService>();

        var resources = _harness.App.Services.GetRequiredService<DistributedApplicationModel>().Resources;
        foreach (var resource in resources)
        {
            await resourceNotificationService.WaitForResourceHealthyAsync(
                resource.Name,
                new CancellationTokenSource(TimeSpan.FromSeconds(60)).Token);
        }
    }
}

